import pytest
from collections import OrderedDict, UserDict

# Import or define the function under test
def flatten_dict(d: dict, parent_key: str = '', sep: str = '.') -> dict:
    items = []
    for k, v in d.items():
        new_key = f'{parent_key}{sep}{k}' if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep).items())
        else:
            items.append((new_key, v))
    return dict(items)


# ---------- Happy Path ----------

def test_flatten_empty_dict():
    """Flattening an empty dictionary returns an empty dictionary."""
    assert flatten_dict({}) == {}

def test_flatten_flat_dict():
    """A dictionary without nested dicts stays the same."""
    input_d = {"a": 1, "b": 2, "c": 3}
    assert flatten_dict(input_d) == input_d

def test_flatten_simple_nested_dict():
    """Single level of nesting produces 'parent.child' keys."""
    input_d = {"a": {"b": 1, "c": 2}, "d": 3}
    expected = {"a.b": 1, "a.c": 2, "d": 3}
    assert flatten_dict(input_d) == expected

def test_flatten_deeply_nested_dict():
    """Multiple nesting levels concatenate keys with the separator."""
    input_d = {"x": {"y": {"z": 10}}}
    expected = {"x.y.z": 10}
    assert flatten_dict(input_d) == expected

def test_flatten_mixed_depths():
    """Keys at different depths are all flattened correctly."""
    input_d = {
        "level1": 1,
        "nested": {
            "level2": 2,
            "deep": {
                "level3": 3,
                "level3b": 4
            }
        },
        "another_level1": 5
    }
    expected = {
        "level1": 1,
        "nested.level2": 2,
        "nested.deep.level3": 3,
        "nested.deep.level3b": 4,
        "another_level1": 5
    }
    assert flatten_dict(input_d) == expected


# ---------- Edge Cases ----------

def test_flatten_custom_separator():
    """A custom separator replaces the default '.'."""
    input_d = {"a": {"b": 1, "c": {"d": 2}}}
    expected = {"a/b": 1, "a/c/d": 2}
    assert flatten_dict(input_d, sep='/') == expected

def test_flatten_with_initial_parent_key():
    """Providing an initial parent_key prefixes all keys."""
    input_d = {"a": {"b": 1}, "c": 2}
    expected = {"prefix.a.b": 1, "prefix.c": 2}
    assert flatten_dict(input_d, parent_key='prefix') == expected

def test_flatten_initial_parent_key_with_sep():
    """Combining parent_key and custom sep works."""
    input_d = {"x": {"y": 1}}
    expected = {"root::x::y": 1}
    assert flatten_dict(input_d, parent_key='root', sep='::') == expected

def test_flatten_empty_nested_dict_omitted():
    """An empty nested dictionary should produce no keys."""
    input_d = {"a": 1, "b": {}}
    expected = {"a": 1}
    assert flatten_dict(input_d) == expected

def test_flatten_all_empty_nested_dicts():
    """All values are empty dicts -> empty result."""
    input_d = {"a": {}, "b": {"c": {}}}
    assert flatten_dict(input_d) == {}

def test_flatten_values_are_lists():
    """Non-dict values like lists are treated as leaves."""
    input_d = {"a": [1, 2], "b": {"c": [3, 4]}}
    expected = {"a": [1, 2], "b.c": [3, 4]}
    assert flatten_dict(input_d) == expected

def test_flatten_values_are_none():
    """None values are kept as leaves."""
    input_d = {"a": None, "b": {"c": None}}
    expected = {"a": None, "b.c": None}
    assert flatten_dict(input_d) == expected

def test_flatten_values_are_integers_floats_bools():
    """Various immutable types are preserved."""
    input_d = {"a": 1, "b": {"c": 2.5, "d": True}}
    expected = {"a": 1, "b.c": 2.5, "b.d": True}
    assert flatten_dict(input_d) == expected

def test_flatten_non_string_keys():
    """Keys that are not strings (e.g., ints) are converted with f-string."""
    input_d = {1: "a", 2: {3: "b"}}
    expected = {1: "a", "2.3": "b"}  # f-string produces '2.3'
    assert flatten_dict(input_d) == expected

def test_flatten_tuple_keys():
    """Tuple keys are converted to their string representation."""
    input_d = {("x", "y"): "z"}
    expected = {("x", "y"): "z"}
    assert flatten_dict(input_d) == expected

def test_flatten_ordered_dict():
    """An OrderedDict (subclass of dict) is flattened as a normal dict."""
    input_d = OrderedDict([("a", OrderedDict([("b", 1)]))])
    expected = {"a.b": 1}
    assert flatten_dict(input_d) == expected

def test_flatten_user_dict():
    """A UserDict (not a dict subclass) is treated as a leaf, not flattened."""
    class MyUserDict(UserDict):
        pass
    inner = MyUserDict({"inner_key": "val"})
    input_d = {"a": inner}
    expected = {"a": inner}
    assert flatten_dict(input_d) == expected

def test_original_dict_is_not_mutated():
    """The function should not modify the original dictionary."""
    original = {"a": {"b": 1}}
    _ = flatten_dict(original)
    assert original == {"a": {"b": 1}}


# ---------- Error Cases ----------

def test_flatten_non_dict_input_list_raises_attribute_error():
    """Passing a list as the initial dict should raise an AttributeError."""
    with pytest.raises(AttributeError):
        flatten_dict([1, 2, 3])

def test_flatten_non_dict_input_string_raises_attribute_error():
    """Passing a string should fail because it has no items()."""
    with pytest.raises(AttributeError):
        flatten_dict("not a dict")

def test_flatten_non_dict_input_integer_raises_attribute_error():
    """Passing an int should raise AttributeError."""
    with pytest.raises(AttributeError):
        flatten_dict(42)
